<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireAuth();$pdo=$db->getConnection();$uid=$auth->getUserId();if($_SERVER['REQUEST_METHOD']==='POST'&&trim($_POST['message']??'')!==''){try{$stmt=$pdo->prepare("INSERT INTO support_messages (user_id,message,sender_type,created_at) VALUES (?,?,'user',NOW())");$stmt->execute([$uid,trim($_POST['message'])]);}catch(Throwable $e){}}$messages=[];try{$stmt=$pdo->prepare("SELECT * FROM support_messages WHERE user_id=? ORDER BY created_at ASC LIMIT 100");$stmt->execute([$uid]);$messages=$stmt->fetchAll();}catch(Throwable $e){}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Support</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5" style="max-width:760px"><h2>Live Support</h2><div class="card mb-3"><div class="card-body" style="max-height:420px;overflow:auto"><?php if(!$messages):?><p class="text-muted">No messages yet.</p><?php endif;?><?php foreach($messages as $m):?><div class="mb-2"><strong><?=htmlspecialchars($m['sender_type']??'user')?>:</strong> <?=htmlspecialchars($m['message'])?><small class="text-muted d-block"><?=htmlspecialchars($m['created_at']??'')?></small></div><?php endforeach;?></div></div><form method="post" class="d-flex gap-2"><input class="form-control" name="message" placeholder="Type a message" required><button class="btn btn-primary">Send</button></form></div></body></html>